"""Publish evidence-based report after all original runs and representative videos finish."""
from pathlib import Path
import json,datetime,csv
D=Path(__file__).resolve().parents[1];A=D/'분석'
def f(x,n=3):return f'{x:.{n}f}' if isinstance(x,(int,float)) else str(x)
def main():
 x=json.loads((A/'요약.json').read_text());sel=x['selections'];final=[r for r in x['comparison'] if r['transitions']==16777216];final.sort(key=lambda r:r['horizon']);base=final[0];candidates=[r for r in final[1:] if r['hold_release_notes']>base['hold_release_notes'] and r['failure_episodes']<=base['failure_episodes']]
 if not any(r['hold_release_notes'] for r in final):decision='현재 경험 예산에서 H의 압현 개선 효과는 판단 불가다. 세 조건 모두 전체 유지·필요 해제 완료 음이 없으면 legacy/보상 차이로 H64/H128을 채택하지 않는다.'
 elif candidates:
  best=max(candidates,key=lambda r:(r['hold_release_notes'],-r['failure_episodes'],r['clean_s']));decision=f"seed7의 추가 재현 검증 후보는 {best['condition']}다. 이번 단회 결과만으로 일반 우위나 기본값 채택을 선언하지 않는다. 기본 학습 코드는 변경하지 않았다."
 else:decision='현재 1차 비교에서는 H32를 유지한다. 더 긴 H가 안전성을 유지하며 전체 유지·해제 완료 음을 늘렸다는 근거가 충분하지 않다. 추가 seed 확인 전 일반적인 최적 H로 결론 내리지 않는다.'
 lines=['# H32·H64·H128 동일 경험량 비교', '',f"작성: {datetime.datetime.now().astimezone().isoformat()}", '',decision,'','## 최종 경험량 결과','','각 조건16,777,216전이·seed7·1024환경·V5 corrected의 새 정책이다. 평가32환경의 최초 episode를 모두 분모에 포함했다. 음 완료는 전체 길이의 연속 clean과 필요한 원래 해제 판정이 함께 맞아야 한다. 일부 음 완료 후 episode가 후반에 실패한 경우와 안전한 전곡 episode 완료를 별도 집계했다.']
 lines+=['','|H|음 전체 유지/640|유지+해제/640|구간 완료/288|전곡 완료/32|물리/손목 종료/32|발음 시작 노출/640|clean 합 초|','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in final:lines.append(f"|{r['horizon']}|{r['strict_hold_notes']}|{r['hold_release_notes']}|{r['section_hold_release_completed']}|{r['episode_completion']}|{r['physical_failure']}/{r['wrist_failure']}|{r['audible_started_notes']}|{r['clean_s']:.3f}|")
 lines+=['','clean/wrong/missing 합계의 초 단위는 여러 환경·음에 걸친 note-seconds이며 실제 경과 초가 아니다. P1~P9 표는 `구간별비교.csv`, 음별 근거는 `음별원장.csv`다. 전체640개 선택 음을 분모로 유지하고, 기하 진단창 노출·발음 시작·음 끝 관측·발음 미도달·도달 후 실패를 따로 표시했다. 원장의 exposure_time은[press−2,end] 기하 진단창 적분이고 실제 정책 목표 토큰의 관측 노출과 같지 않다. 관측 토큰은 t0부터 먼저 보일 수 있지만 전 환경의 실제 goal mask 이력이 없어 그 노출 횟수는 미기록으로 남겼다. 늦은 목표의 missing 값이0이어도 실패 전에 그 목표가 발음되지 않았을 수 있다. 이0을 성공이나 누락 없음으로 해석하지 않는다. 병렬32환경은 독립적으로 훈련한32개 seed가 아니다.','','## 시간과 최적화 비용','','|H|native 보고 소요 시간 초|수집 시간 초|최적화 시간 초|수락 actor 미니배치|거절 actor 미니배치|value 미니배치|KL 재시도|','|---|---:|---:|---:|---:|---:|---:|---:|']
 for r in final:
  t=x['training'][r['condition']];lines.append(f"|{r['horizon']}|{t['report_wall_s']:.1f}|{t['collection_s']:.1f}|{t['optimization_s']:.1f}|{t['accepted_actor_steps']}|{t['rejected_actor_steps']}|{t['value_steps']}|{t['KL_retries']}|")
 lines+=['','실제 경과 시간 그래프는 native events의 UTC와 감독이 기록한 실행 시작 시각의 차이를 사용하며 최종점은 감독의 완료 측정값이다. 수집+업데이트 구간 합도 별도 보존했다. 원래 update_s는 PPO 계산과 journal/schedule commit 등을 포함한 업데이트 구간이며 순수 GPU optimizer kernel 시간만은 아니다. 전송·검토·렌더 시간을 학습 수집 시간으로 포함하지 않았다. H는0.533/1.067/2.133초이며 배치도32768/65536/131072로 변하고 PPO 반복 빈도도 달라진다. 따라서 순수 신용 할당 길이 효과를 분리한 실험은 아니다. 같은 경험량에서도 실제 수락/거절 optimizer 단계는 기록으로 비교해야 한다.','','![경험량 대비 음 완료](experience_hold_release_rate.png)','','![실제 경과시간 대비 음 완료](time_hold_release_rate.png)','','![구간 완료](experience_section_hold_release_rate.png)','','![정책 갱신 진단](학습진단.png)','','## 원장·학습 신호의 해석','','`학습지표.csv`는9항 보상 평균, LR·KL·재시도·clip·entropy·critic explained variance와 수집/최적화 시간을 실제 기록에서 읽었다. Value loss는 마지막 미니배치 값, explained variance는 업데이트 후 valid decision의 값이다. 보상 평균이나 raw advantage 표준편차 비율만으로 gradient 지배를 단정하지 않는다. `탐색표준편차.csv`의33축 값은 다섯 실제 checkpoint에서 원래 clamp를 적용해 읽은 latent Gaussian 표준편차이며 물리적 관절각 표준편차가 아니다. 없는 rollout 경사·전체 시점의 접촉 witness를 추정치로 채우지 않았다.','','전체 유지·필요 해제·겹치는 target coordination 구간 판정은 공식 원장을 대조했다. 첫 접촉은 press..end의 계약에 따른0.05초 조건이며 음 전체 유지와 다르다. legacy 달성은학습의40% 문턱을 반영하므로 strict 성공으로 바꾸지 않았다. 힘/하중 proxy는 실제 현 압력·음향 측정이 아니다.','','## 초기 상태·입력·노출 검증','','세 조건의 초기 model state tensor SHA가 같음을 확인했다. 보상·제어·목표·source clock·정책·LR/탐색 초기값은 봉인된 그대로다. 실제 설정의 차이는 horizon/updates/checkpoint_every뿐이며 감독이 검산했다. 노출 계획은 각각 planned16777216/full_song_after4194304이고 문턱 뒤 새 reset부터 전곡을 적용했다. 실제 phrase/full-song 노출 전이는 `요약.json`의 training.actual_exposure에 있다. 기존 다른 PC의 장기 C1 학습은 대조군으로 사용하지 않았다.','','소스는 전달된9338항목의 준비 사본을 로컬 디스크에서 검사·실행했다. 최초 복사에서 native 상대링크17개를 누락한 오류는 원문/봉인과 같은 링크를 복원해 해결했고 첫 실패 로그를 보존했다. 봉인·입력·모델 identity를 고쳐 통과시키지 않았다. 환경 기록과 메모리 검사는 `../검증/다른PC_환경.json`, `../검증/H128_메모리검사.json`에 있다. 메모리 사전검사의131072전이는 본 성과에 포함하지 않았다. 최고 VRAM/RSS는 각각1초 또는2초 샘플의 GPU전체/프로세스 트리 값이며 정확한 tensor 메모리 최고치라고 주장하지 않는다.','','## 대표 모델과 영상','','모델 선택 순서는 음 전체 유지+필요 해제 완료율→물리/손목 안전성→clean 시간이며 동률이면 final이다. 같은 C1 평가로 고른 결과는 독립 테스트셋 성과가 아니다. 영상은 원래 renderer의 env0 첫 episode,1환경·평균 정책으로 기록하여32환경 집계의 대용물이 아니다. 준비·구간 중 조기 종료해 짧은 영상이라면 그 실패를 그대로 남긴다.']
 for name,v in sel.items():lines+=['',f"- {name}: 전이{v['transitions']}, SHA `{v['sha256']}`."]
 videos=json.loads((A/'영상검증.json').read_text());assert len(videos['videos'])==6
 for v in videos['videos']:lines+=['',f"[{v['file']}](../동영상/{v['file']}) — {v['duration_s']:.3f}초, 전체 디코딩 통과."]
 lines+=['','## 다음 검증과 채택 범위','','seed7 한 번의 선별 비교다. 추가 seed17에서 H32와 우선 후보 하나를 같은 경험량으로 재확인하는 것이 우선이다. 현재 비교에서 판정 범위가 작거나 전체 유지·해제 완료가 없으면 학습 길이·보상·탐색·초기 자세를 동시에 바꾸지 않고 실패가 발음 구간 미도달인지 도달 후 정밀 압현/해제 실패인지 먼저 구분한다. GPU/배치의 수치 민감성을 독립 훈련 seed 차이와 혼동하지 않는다. H 설정 추천과 기본 동작 변경은 구분하며 이번 실행에서 보상·제어·학습률·탐색값이나 기본 코드는 수정하지 않았다.']
 (A/'REPORT.md').write_text('\n'.join(lines)+'\n');print(decision)
if __name__=='__main__':main()
